int boton = 2;
int led = 13;

void setup() {
    pinMode(boton, INPUT);  // Configura el pin 2 como entrada
    pinMode(led, OUTPUT);   // Configura el pin 13 como salida
}

void loop() {
    // Si el botón devuelve HIGH (presionado), enciende el LED
    if (digitalRead(boton) == HIGH) {
        digitalWrite(led, HIGH);
    } else {
        digitalWrite(led, LOW);
    }
}
